function pickupChange(kind, player) {
  const field=kind==="bomb+"?"bombMax":kind==="fire+"?"bombPower":"speed";
  const label=kind==="bomb+"?"弹量":kind==="fire+"?"火力":"移速";
  const before=player[field];
  const after=Math.min(kind==="bomb+"?6:kind==="fire+"?8:224,before+(kind==="speed"?14:1));
  return {field,label,before,after};
}
function applyPickupUpgrade(pickup, player) {
  const {field,label,before,after}=pickupChange(pickup.kind,player);
  player[field]=after;
  showFeedback(after>before?`${label} ${before}→${after} · +80分`:`${label}已满 · +80分`);
}
function refreshPickupOffer() {
  let copy="";
  const p=Game.player;
  if(Game.state==="playing"&&p&&!Game.trial&&!Game.opening&&!Game.exitTimer&&Game.pickups.length){
    let best=null, dist2=Infinity;
    for(const item of Game.pickups){
      if(Math.abs(item.col-p.col)+Math.abs(item.row-p.row)>1)continue;
      const dx=p.px-OX-(item.col+.5)*CELL, dy=p.py-OY-(item.row+.5)*CELL;
      const d=dx*dx+dy*dy;
      if(d>=(CELL*.62)**2&&d<=(CELL*1.35)**2&&d<dist2){best=item;dist2=d}
    }
    if(best){
      const {label,before,after}=pickupChange(best.kind,p);
      copy=after>before?`拾取 · ${label} ${before}→${after} · +80分`:`拾取 · ${label}已满 · +80分`;
    }
  }
  const node=$id("pickup-offer");
  if(node.textContent!==copy)node.textContent=copy;
}
